namespace ghidra.app.plugin.core.decompile.actions;



using docking.action;
using ghidra.app.plugin.core.decompile;
using ghidra.app.util;
using ghidra.pcode.floatformat;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.pcode;
using ghidra.program.model.scalar;
using ghidra.util;

public class ConvertFloatAction : ConvertConstantAction {

	public ConvertFloatAction(DecompilePlugin plugin) : base(plugin, "Convert To Float", EquateSymbol.FORMAT_FLOAT)
    {
		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ActionConvert"));
		setPopupMenuData(new MenuData(new string[] { "Float" }, "Decompile"));
	}

	/* @Override */
	public string getMenuPrefix() {
		return "Float: ";
	}

	/* @Override */
	public string getMenuDisplay(Scalar scalar, Program program) {
		return getText(scalar, program);
	}

	/* @Override */
	public string getEquateName(Scalar scalar, Program program) {
		return getText(scalar, program);
	}

	private string getText(Scalar scalar, Program program) {
		DataOrganization organization = program.getDataTypeManager().getDataOrganization();
		int floatSize = organization.getFloatSize();
		BigDecimal bd = value(floatSize, scalar);
		if (bd != null) {
			return bd.toString();
		}
		return null;
	}

	private static BigDecimal value(int size, Scalar s) {
		try {
			FloatFormat format = FloatFormatFactory.getFloatFormat(size);
			return format.round(format.decodeBigFloat(s.getBigInteger()));
		}
		catch (UnsupportedFloatFormatException e) {
			return null;
		}
	}
}
